	internal class _Anon_InputVerifier_2 : InputVerifier
	{

				/* @Override */
				public bool verify(JComponent input) {
					setStatus("");
					string dbName = nameField.getText().trim();
					if (dbName.length() == 0) {
						setStatus("");
						return false;
					}
					// Naming restrictions based upon PostgreSQL and its allowance of unicode chars
					for (int i = 0; i < dbName.length(); i++) {
						char c = dbName.charAt(i);
						if (Character.isLetter(c)) {
							continue;
						}
						if (i == 0 || (!Character.isDigit(c) && c != '_')) {
							setStatus("Unsupported database name");
							return false;
						}
					}
					return true;
				}

				/* @Override */
				public bool shouldYieldFocus(JComponent source, JComponent target) {
					return true;
				}
			
	}


